        <text id="gaugeText" x="60" y="55" text-anchor="middle" 
              font-size="24" font-weight="bold" fill="#fff">—</text>
        <text id="gaugeSubtext" x="60" y="75" text-anchor="middle" 
              font-size="11" fill="#9ca3af">health</text>
      </svg>
    </div>
    <div class="overall-info">
      <div class="overall-status" id="overallStatus">—</div>
