  <div class="dimension-grid" id="dimensionGrid"></div>

  <div class="detail-section">
    <div class="section-title">📊 Artifact Distribution</div>
    <div class="category-chart" id="categoryChart"></div>
  </div>

  <div class="detail-section">
    <div class="section-title">🚨 Incidents & Observations</div>
    <ul class="incident-list" id="incidentList"></ul>
