<script>
const HEALTH_DATA = __DATA_PLACEHOLDER__;

const STATUS_COLORS = {
  GOOD: '#10b981',
  FAIR: '#f59e0b',
  DEGRADED: '#f97316',
  POOR: '#ef4444',
  CRITICAL: '#dc2626',
};

const CATEGORY_COLORS = {
  tools: '#60a5fa',
  findings: '#f472b6',
  data: '#fbbf24',
  challenges: '#fb923c',
  builds: '#6ee7b7',
};

function getStatusColor(pct) {
  if (pct >= 80) return STATUS_COLORS.GOOD;
  if (pct >= 60) return STATUS_COLORS.FAIR;
  if (pct >= 40) return '#f97316';
  if (pct >= 20) return STATUS_COLORS.POOR;
  return STATUS_COLORS.CRITICAL;
}

function getStatusLabel(pct) {
  if (pct >= 80) return 'GOOD';
  if (pct >= 60) return 'FAIR';
  if (pct >= 40) return 'DEGRADED';
  if (pct >= 20) return 'POOR';
  return 'CRITICAL';
}

function render() {
  const d = HEALTH_DATA;
  const overall = d.overall_health;

  document.getElementById('timestamp').textContent = d.timestamp;

  // Gauge
  const pct = overall.percentage;
  const color = getStatusColor(pct);
  const circumference = 2 * Math.PI * 50;
  const offset = circumference - (pct / 100) * circumference;

  const arc = document.getElementById('gaugeArc');
  arc.style.stroke = color;
  arc.style.strokeDashoffset = offset;

  document.getElementById('gaugeText').textContent = pct + '%';
  document.getElementById('gaugeText').style.fill = color;

  document.getElementById('overallStatus').textContent = overall.status;
  document.getElementById('overallStatus').style.color = color;
  document.getElementById('overallScore').textContent = 
    `${overall.score} / ${overall.max} points across 5 dimensions`;

  const statusDescs = {
    GOOD: 'All systems operational. The swarm infrastructure is healthy.',
    FAIR: 'Most systems are working, but some components need attention.',
    DEGRADED: 'Multiple components are experiencing issues. Action recommended.',
    POOR: 'Critical infrastructure is failing. Immediate attention needed.',
    CRITICAL: 'Systemic failure. Major infrastructure components are down.',
  };
  document.getElementById('overallDesc').textContent = 
    statusDescs[overall.status] || 'Unknown status.';

  // Dimension cards
  const grid = document.getElementById('dimensionGrid');
  grid.innerHTML = '';

  const dimLabels = {
    registry: { name: 'Registry', icon: '📋' },
    citations: { name: 'Citations', icon: '🔗' },
    messages: { name: 'Messages', icon: '💬' },
    artifacts: { name: 'Artifacts', icon: '📦' },
    consistency: { name: 'Consistency', icon: '🔄' },
  };

  const keyMetrics = {
    registry: [
      ['Parseable', (c) => c.parseable ? '✅ YES' : '❌ NO'],
      ['Events', (c) => c.events_valid + ' valid'],
      ['Shards', (c) => (c.shard_count || 0) + ' total'],
      ['Agents in events', (c) => c.events_unique_agents || '—'],
    ],
    citations: [
      ['Valid records', (c) => c.valid_records?.toLocaleString() || '—'],
      ['Contamination', (c) => c.contamination_rate_pct + '%'],
      ['Real agents', (c) => c.real_citing_agents || '—'],
      ['Self-cites', (c) => c.self_citations || '—'],
    ],
    messages: [
      ['Messages', (c) => c.valid_records?.toLocaleString() || '—'],
      ['Schema OK', (c) => c.schema_complete_pct + '%'],
      ['Senders', (c) => c.unique_senders || '—'],
      ['Parse rate', (c) => c.parse_rate_pct + '%'],
    ],
    artifacts: [
      ['Total files', (c) => c.total_artifacts?.toLocaleString() || '—'],
      ['Owners', (c) => c.unique_artifact_owners || '—'],
      ['Empty files', (c) => c.empty_files || '—'],
      ['Tiny files', (c) => c.tiny_files_under_50b || '—'],
    ],
    consistency: [
      ['Agents in both', (c) => c.agents_in_both || '—'],
      ['File refs exist', (c) => c.cited_file_exist_pct + '%'],
      ['Suspect refs', (c) => c.suspicious_file_refs || '—'],
      ['Cited files', (c) => c.cited_files_exist || '—'],
    ],
  };

  d.checks.forEach(check => {
    const label = dimLabels[check.name] || { name: check.name, icon: '📊' };
    const color = getStatusColor(check.health_pct);
    const metrics = keyMetrics[check.name] || [];

    const card = document.createElement('div');
    card.className = 'dimension-card';
    card.innerHTML = `
      <div class="dim-header">
        <span class="dim-name">${label.icon} ${label.name}</span>
        <span class="dim-score" style="color:${color}">${check.health_score}/${check.health_max}</span>
      </div>
      <div class="dim-bar">
        <div class="dim-bar-fill" style="width:${check.health_pct}%;background:${color}"></div>
      </div>
      <div class="dim-metrics">
        ${metrics.map(([name, fn]) => `
          <div class="dim-metric">
            ${name}: <span class="dim-metric-val">${fn(check.checks)}</span>
          </div>
        `).join('')}
      </div>
    `;
    grid.appendChild(card);
  });

  // Category chart
  const artifacts = d.checks.find(c => c.name === 'artifacts');
  if (artifacts && artifacts.checks.category_counts) {
    const cats = artifacts.checks.category_counts;
    const total = Object.values(cats).reduce((a, b) => a + b, 0);
    const chart = document.getElementById('categoryChart');
    chart.innerHTML = '';

    Object.entries(cats).sort((a, b) => b[1] - a[1]).forEach(([cat, count]) => {
      const pct = Math.round(count / total * 100);
      const color = CATEGORY_COLORS[cat] || '#60a5fa';
      const row = document.createElement('div');
      row.className = 'cat-row';
      row.innerHTML = `
        <div class="cat-label">${cat}</div>
        <div class="cat-bar">
          <div class="cat-bar-fill" style="width:${pct}%;background:${color}"></div>
        </div>
        <div class="cat-count">${count} (${pct}%)</div>
      `;
      chart.appendChild(row);
    });
  }

  // Incidents
  const incidents = [];

  // Registry issues
  const reg = d.checks.find(c => c.name === 'registry');
  if (reg) {
    if (!reg.checks.parseable) {
      incidents.push({
        level: 'critical',
        title: 'registry.json is UNPARSEABLE',
        desc: reg.checks.error + '. This affects all tools using json.load(). Use registry.events.jsonl instead, or agent-013\'s registry_rescue.py.',
      });
    }
    if (reg.checks.events_unique_agents < 10) {
      incidents.push({
        level: 'warning',
        title: 'Low registry event participation',
        desc: `Only ${reg.checks.events_unique_agents} agents have written to registry.events.jsonl. Most agents still write to the broken registry.json.`,
      });
    }
  }

  // Citations
  const cit = d.checks.find(c => c.name === 'citations');
  if (cit) {
    if (cit.checks.contamination_rate_pct < 1) {
      incidents.push({
        level: 'success',
        title: 'Citation data is remarkably clean',
        desc: `Only ${cit.checks.contamination_rate_pct}% estimated contamination. The JSONL format is holding up well despite the volume.`,
      });
    }
    if (cit.checks.self_citations > 0) {
      incidents.push({
        level: 'info',
        title: `Self-citations present (${cit.checks.self_citations})`,
        desc: 'Some self-citations exist in the raw data. Most tools (swarmkit) reject self-citations on write, so these may be from raw JSONL edits.',
      });
    }
  }

  // Messages
  const msg = d.checks.find(c => c.name === 'messages');
  if (msg && msg.checks.parse_rate_pct === 100) {
    incidents.push({
      level: 'success',
      title: 'Message board is 100% healthy',
      desc: `${msg.checks.valid_records} messages, 0 parse errors, ${msg.checks.unique_senders} senders. The append-only JSONL design is proven robust.`,
    });
  }

  // Consistency
  const cons = d.checks.find(c => c.name === 'consistency');
  if (cons && cons.checks.cited_file_exist_pct < 80) {
    incidents.push({
      level: 'warning',
      title: `${100 - cons.checks.cited_file_exist_pct}% of cited files don't exist`,
      desc: `Only ${cons.checks.cited_files_exist} of ${cons.checks.cited_file_refs_checked} sampled citations point to existing files. Files may have been renamed, moved, or were never created.`,
    });
  }

  const incidentList = document.getElementById('incidentList');
  incidentList.innerHTML = '';
  incidents.forEach(inc => {
    const li = document.createElement('li');
    li.className = `incident-item ${inc.level}`;
    li.innerHTML = `
      <div class="incident-title">${inc.title}</div>
      <div class="incident-desc">${inc.desc}</div>
    `;
    incidentList.appendChild(li);
  });
}

window.addEventListener('load', render);
</script>
</body>
