{"content": "#!/usr/bin/env python3
"""
swarmtest — lightweight testing framework for swarm tools.

Pure stdlib, zero dependencies, read-only by design.
No file modification unless explicitly requested via --write.

Features:
  - Decorator-based test registration (@test, @before, @after)
  - Assertions: assert_eq, assert_ne, assert_true, assert_contains, assert_raises
  - Test suites with setup/teardown
  - JSON and text output formats
  - Exit code 0 if all pass, 1 if any fail
  - Selective test running by name or tag

Usage:
  # As a library (write your own test file):
    from agent-033_swarmtest import test, assert_eq, run_tests

    @test
    def my_test():
        assert_eq(2 + 2, 4)

    run_tests()

  # Run a test file:
    python3 swarmtest.py run path/to/test_file.py
    python3 swarmtest.py run path/to/test_file.py --format json
    python3 swarmtest.py run path/to/test_file.py --filter "name_pattern"

  # Self-test:
    python3 swarmtest.py selftest
"""

import sys
import os
import json
import time
import traceback
import re
from pathlib import Path
from collections import defaultdict

VERSION = "0.1.0"
AGENT_ID = "agent-033"

# ── Test registry ──────────────────────────────────────────────────────────

_tests = []
_before_fns = []
_after_fns = []
_test_tags = defaultdict(set)


def test(func=None, tags=None):
    """Decorator to register a test function."""
    def decorator(f):
        _tests.append(f)
        if tags:
            for tag in tags:
                _test_tags[tag].add(f.__name__)
        return f
    if func:
        return decorator(func)
    return decorator


def before(func):
    """Decorator to register a setup function."""
    _before_fns.append(func)
    return func


def after(func):
    """Decorator to register a teardown function."""
    _after_fns.append(func)
    return func


# ── Assertions ─────────────────────────────────────────────────────────────

class AssertionError(Exception):
    pass


def assert_eq(actual, expected, msg=""):
    if actual != expected:
        raise AssertionError(
            f"Expected {expected!r}, got {actual!r}" + (f": {msg}" if msg else "")
        )


def assert_ne(actual, unexpected, msg=""):
    if actual == unexpected:
        raise AssertionError(
            f"Expected not {unexpected!r}, got {actual!r}" + (f": {msg}" if msg else "")
        )


def assert_true(condition, msg=""):
    if not condition:
        raise AssertionError("Assertion failed" + (f": {msg}" if msg else ""))


def assert_false(condition, msg=""):
    if condition:
        raise AssertionError("Expected false, got true" + (f": {msg}" if msg else ""))


def assert_contains(container, item, msg=""):
    if item not in container:
        raise AssertionError(
            f"Expected {item!r} in {container!r}" + (f": {msg}" if msg else "")
        )


def assert_not_contains(container, item, msg=""):
    if item in container:
        raise AssertionError(
            f"Did not expect {item!r} in {container!r}" + (f": {msg}" if msg else "")
        )


def assert_raises(exc_type, func, *args, **kwargs):
    try:
        func(*args, **kwargs)
    except exc_type:
        return
    except Exception as e:
        raise AssertionError(
            f"Expected {exc_type.__name__}, got {type(e).__name__}: {e}"
        )
    raise AssertionError(f"Expected {exc_type.__name__} to be raised")


def assert_gt(a, b, msg=""):
    if not (a > b):
        raise AssertionError(f"Expected {a} > {b}" + (f": {msg}" if msg else ""))


def assert_lt(a, b, msg=""):
    if not (a < b):
        raise AssertionError(f"Expected {a} < {b}" + (f": {msg}" if msg else ""))


def assert_gte(a, b, msg=""):
    if not (a >= b):
        raise AssertionError(f"Expected {a} >= {b}" + (f": {msg}" if msg else ""))


def assert_lte(a, b, msg=""):
    if not (a <= b):
        raise AssertionError(f"Expected {a} <= {b}" + (f": {msg}" if msg else ""))


def assert_isinstance(obj, cls, msg=""):
    if not isinstance(obj, cls):
        raise AssertionError(
            f"Expected instance of {cls.__name__}, got {type(obj).__name__}"
            + (f": {msg}" if msg else "")
        )


def assert_in_delta(a, b, delta=0.001, msg=""):
    if abs(a - b) > delta:
        raise AssertionError(
            f"Expected {a} ≈ {b} (delta={delta}), diff={abs(a-b)}"
            + (f": {msg}" if msg else "")
        )


# ── Test runner ────────────────────────────────────────────────────────────

def run_tests(filter_pattern=None, tag=None, format_output="text"):
    """Run all registered tests and print results.

    Returns (passed, failed, errors, results_list).
    """
    selected = _tests[:]

    # Filter by name pattern
    if filter_pattern:
        pat = re.compile(filter_pattern, re.IGNORECASE)
        selected = [t for t in selected if pat.search(t.__name__)]

    # Filter by tag
    if tag:
        tag_tests = _test_tags.get(tag, set())
        selected = [t for t in selected if t.__name__ in tag_tests]

    results = []
    passed = 0
    failed = 0
    errors = 0
    skipped = 0
    total_time = 0

    # Run setup
    for fn in _before_fns:
        try:
            fn()
        except Exception as e:
            print(f"SETUP FAILED in {fn.__name__}: {e}")
            return 0, 1, 0, []

    for test_func in selected:
        test_name = test_func.__name__
        start = time.time()
        try:
            test_func()
            elapsed = time.time() - start
            passed += 1
            results.append({
                "name": test_name,
                "status": "PASS",
                "duration": round(elapsed * 1000, 2),
            })
            if format_output == "text":
                print(f"  ✓ {test_name} ({elapsed*1000:.1f}ms)")
        except AssertionError as e:
            elapsed = time.time() - start
            failed += 1
            results.append({
                "name": test_name,
                "status": "FAIL",
                "duration": round(elapsed * 1000, 2),
                "error": str(e),
            })
            if format_output == "text":
                print(f"  ✗ {test_name} — {e}")
        except Exception as e:
            elapsed = time.time() - start
            errors += 1
            tb = traceback.format_exc()
            results.append({
                "name": test_name,
                "status": "ERROR",
                "duration": round(elapsed * 1000, 2),
                "error": str(e),
                "traceback": tb,
            })
            if format_output == "text":
                print(f"  💥 {test_name} — ERROR: {e}")
                print(f"     {tb.strip().split(chr(10))[-1]}")
        total_time += elapsed

    # Run teardown
    for fn in _after_fns:
        try:
            fn()
        except Exception as e:
            print(f"TEARDOWN FAILED in {fn.__name__}: {e}")

    if format_output == "text":
        total = passed + failed + errors
        print()
        print(f"Ran {total} tests in {total_time*1000:.1f}ms")
        print(f"  ✓ {passed} passed")
        if failed:
            print(f"  ✗ {failed} failed")
        if errors:
            print(f"  💥 {errors} errors")
        if skipped:
            print(f"  ⊘ {skipped} skipped")

    report = {
        "version": VERSION,
        "agent": AGENT_ID,
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "summary": {
            "total": passed + failed + errors,
            "passed": passed,
            "failed": failed,
            "errors": errors,
            "duration_ms": round(total_time * 1000, 2),
            "all_passed": failed == 0 and errors == 0,
        },
        "tests": results,
    }

    return passed, failed, errors, report


# ── CLI ────────────────────────────────────────────────────────────────────

def _run_test_file(filepath, fmt="text", filter_pat=None, tag=None):
    """Run tests from an external test file."""
    filepath = Path(filepath).resolve()
    if not filepath.exists():
        print(f"Error: test file not found: {filepath}")
        return 1

    # Clear global state before running external file
    global _tests, _before_fns, _after_fns, _test_tags
    _tests = []
    _before_fns = []
    _after_fns = []
    _test_tags = defaultdict(set)

    # Execute the test file
    code = filepath.read_text(encoding='utf-8')
    globals_dict = {
        "__name__": "__test_module__",
        "__file__": str(filepath),
    }
    try:
        exec(code, globals_dict)
    except Exception as e:
        print(f"Error loading test file: {e}")
        traceback.print_exc()
        return 1

    passed, failed, errors, report = run_tests(
        filter_pattern=filter_pat, tag=tag, format_output=fmt
    )

    if fmt == "json":
        print(json.dumps(report, indent=2, ensure_ascii=False))

    return 0 if (failed == 0 and errors == 0) else 1


def _selftest():
    """Run self-tests to verify the framework works."""

    @test
    def test_assert_eq_passes():
        assert_eq(1, 1)
        assert_eq("hello", "hello")
        assert_eq([1, 2, 3], [1, 2, 3])

    @test
    def test_assert_eq_fails():
        try:
            assert_eq(1, 2)
        except AssertionError:
            return
        raise AssertionError("assert_eq should have raised")

    @test
    def test_assert_ne_passes():
        assert_ne(1, 2)
        assert_ne("a", "b")

    @test
    def test_assert_true_false():
        assert_true(1 == 1)
        assert_false(1 == 2)

    @test
    def test_assert_contains():
        assert_contains([1, 2, 3], 2)
        assert_contains("hello world", "world")

    @test
    def test_assert_raises():
        def raise_value_error():
            raise ValueError("test")
        assert_raises(ValueError, raise_value_error)

    @test
    def test_assert_gt_lt():
        assert_gt(5, 3)
        assert_lt(3, 5)
        assert_gte(5, 5)
        assert_lte(5, 5)

    @test
    def test_assert_isinstance():
        assert_isinstance([], list)
        assert_isinstance("hello", str)

    @test
    def test_assert_in_delta():
        assert_in_delta(1.0, 1.0001, delta=0.01)
        assert_in_delta(0.1 + 0.2, 0.3, delta=0.01)

    @test(tags=["math"])
    def test_math_basic():
        assert_eq(2 + 3, 5)
        assert_eq(10 - 4, 6)
        assert_eq(3 * 7, 21)

    passed, failed, errors, report = run_tests(format_output="text")
    print()
    print(f"Self-test: {'PASSED' if report['summary']['all_passed'] else 'FAILED'}")
    return 0 if report['summary']['all_passed'] else 1


def main():
    args = sys.argv[1:]

    if not args or args[0] in ("-h", "--help", "help"):
        print(__doc__)
        return

    cmd = args[0]

    if cmd == "selftest":
        sys.exit(_selftest())

    elif cmd == "run":
        if len(args) < 2:
            print("Usage: swarmtest.py run <test_file.py> [--format json|text] [--filter pattern] [--tag tag]")
            sys.exit(1)
        test_file = args[1]
        fmt = "text"
        filter_pat = None
        tag = None
        i = 2
        while i < len(args):
            if args[i] == "--format" and i + 1 < len(args):
                fmt = args[i + 1]
                i += 2
            elif args[i] == "--filter" and i + 1 < len(args):
                filter_pat = args[i + 1]
                i += 2
            elif args[i] == "--tag" and i + 1 < len(args):
                tag = args[i + 1]
                i += 2
            else:
                i += 1
        sys.exit(_run_test_file(test_file, fmt=fmt, filter_pat=filter_pat, tag=tag))

    elif cmd == "version":
        print(f"swarmtest v{VERSION}")
    else:
        print(f"Unknown command: {cmd}")
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()
